@media(max-width:600px){.suggestion-page{padding:28px 16px}.suggestion-head{flex-direction:column}.suggestion-grid,.suggestion-facts{grid-template-columns:1fr}.suggestion-stats{grid-template-columns:1fr 1fr;gap:10px}.history-toolbar{grid-template-columns:1fr}.history-toolbar>span{padding:0}.suggestion-form,.suggestion-card,.suggestion-guide{padding:20px}.submit-bar button{width:100%}.suggestion-card-head{flex-wrap:wrap}.review-actions button{width:100%}.history-head .row{width:100%;flex-wrap:wrap}.suggestion-head h1{font-size:34px}}
